import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { openMkf, readChunk, chunkCount } from './packages/shared/src/mkf.ts';
import { decodeRle } from './packages/shared/src/rle.ts';
const path = 'data/raw/GOP.MKF';
const bytes = new Uint8Array(readFileSync(path));
const sha = (value) => createHash('sha256').update(value).digest('hex');
const mkf = openMkf(bytes);
let valid = 0, invalid = 0, skipped = 0, malformedTables = 0;
const divergent = [], invalidExamples = [];
for (let chunkId = 0; chunkId < chunkCount(mkf); chunkId++) {
 const chunk = readChunk(mkf,chunkId);
 if (chunk.length < 2) { skipped++; continue; }
 const view = new DataView(chunk.buffer,chunk.byteOffset,chunk.byteLength);
 const count = view.getUint16(0,true);
 if (count * 2 > chunk.length) { malformedTables++; continue; }
 for (let slot = 0; slot < count; slot++) {
  const offset = view.getUint16(slot*2,true)*2;
  if (offset === 0 || offset+4 > chunk.length) { skipped++; continue; }
  const width = view.getUint16(offset,true), height = view.getUint16(offset+2,true);
  if (!width || !height || width > 400 || height > 400) { skipped++; continue; }
  const frame = chunk.subarray(offset);
  try {
   decodeRle(frame); valid++;
   let source = 4, destination = 0;
   while (destination < width*height) {
    const position = source, command = frame[source++];
    if (command >= 128) {
     if (command > 128+width) divergent.push({chunkId,slot,width,height,position,command});
     destination += command-128;
    } else { source += command; destination += command; }
   }
  } catch (reason) { invalid++; if(invalidExamples.length < 12) invalidExamples.push({chunkId,slot,error:reason.message}); }
 }
}
console.log(JSON.stringify({path,inputSha256:sha(bytes),chunks:chunkCount(mkf),valid,invalid,skipped,malformedTables,
 divergentCommands:divergent.length,divergentExamples:divergent.slice(0,12),invalidExamples,inputUnchanged:sha(readFileSync(path))===sha(bytes),
 limits:'Structural trace of current TS-successful GOP slots only; no native SDL comparison or other archive census'}));
